static void msgin_set_async ( struct AdapterCtlBlk * acb , struct ScsiReqBlk * srb ) { struct DeviceCtlBlk * dcb = srb -> dcb ; dprintkl ( KERN_DEBUG , "msgin_set_async: No sync transfers<%02i-%i>\n" , dcb -> target_id , dcb -> target_lun ) ; dcb -> sync_mode &= ~ ( SYNC_NEGO_ENABLE ) ; dcb -> sync_mode |= SYNC_NEGO_DONE ; dcb -> sync_offset = 0 ; srb -> state &= ~ SRB_DO_SYNC_NEGO ; reprogram_regs ( acb , dcb ) ; if ( ( dcb -> sync_mode & WIDE_NEGO_ENABLE ) && ! ( dcb -> sync_mode & WIDE_NEGO_DONE ) ) { build_wdtr ( acb , dcb , srb ) ; DC395x_ENABLE_MSGOUT ; dprintkdbg ( DBG_0 , "msgin_set_async(rej): Try WDTR anyway\n" ) ; } } 